sys_script_include.script:
var ProcurementFormProcessor = Class.create();
ProcurementFormProcessor.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    processFormSubmission: function() {
        try {
            var formDataString = this.getParameter('sysparm_form_data');
            var formData = JSON.parse(formDataString);

            // Extract instance URL
            var instanceUrl = formData.u_instance_url;

            if (!instanceUrl || instanceUrl.trim() === '') {
                return JSON.stringify({
                    success: false,
                    message: "Missing instance URL"
                });
            }

            // Save to table
            var gr = new GlideRecord('x_985627_proc_form_procurement_form');
            gr.addQuery('u_instance_url', instanceUrl);
            gr.query();

            var recordExists = gr.next();
            var tableOperation = recordExists ? "updated" : "created";

            if (!recordExists) {
                gr.initialize();
            }

            // Set all form fields
            for (var field in formData) {
                if (gr.isValidField(field)) {
                    gr.setValue(field, formData[field]);
                }
            }

            var tableResult = recordExists ? gr.update() : gr.insert();

            return JSON.stringify({
                success: true,
                message: "Form data " + tableOperation + " successfully."
            });
        } catch(e) {
            gs.log("Error in processFormSubmission: " + e, "ProcurementForm");
            return JSON.stringify({
                success: false,
                message: "Server error: " + e.message
            });
        }
    },

    type: 'ProcurementFormProcessor'
});
